async function getPricingAndDetails(url) {
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 15000 });
  return await browserjs(tabId, () => {
    // Find pricing text
    const text = document.body.innerText;
    const priceMatches = text.match(/(Tuition|Price|Pricing|Investment|Cost)[\s\S]{1,400}/i);
    const dateMatch = text.match(/(Date|When|Schedule|Time)[\s\S]{1,200}/i);
    const locationMatch = text.match(/(Location|Where|Address)[\s\S]{1,200}/i);
    return {
      title: document.title,
      priceSnippet: priceMatches ? priceMatches[0] : "Not explicitly matched",
      allDollarAmounts: text.match(/\$[\d,]+(\.\d{2})?/g)
    };
  });
}

