const tabId = 725789690;
const campRows = await browserjs(tabId, () => {
  // Let's find each camp entry
  const rows = document.querySelectorAll('.schedule-result, .result-row, [class*="result"]');
  // Let's see what classes exist around the results
  const container = document.querySelector('.schedule-results, #schedule-results, .camps-list') || document.body;

  // Let's find all items that have dates and locations
  const items = Array.from(document.querySelectorAll('.schedule-table-row, .camp-row, tr, div')).filter(el => {
    return el.querySelector('.result-course') || el.classList.contains('result-row');
  });

  // If not found, let's look at the parent of .result-course
  const courseEls = Array.from(document.querySelectorAll('.result-course'));
  return courseEls.map(el => {
    const parent = el.closest('tr') || el.parentElement;
    return parent ? parent.innerText.replace(/\n+/g, ' | ') : el.innerText;
  });
});
console.log("Total camp items found:", campRows.length);
console.log("First 10 camp items:", campRows.slice(0, 10));

