const tabId = 725789907;
const southBayLinks = await browserjs(tabId, () => {
  const cards = Array.from(document.querySelectorAll('div, section, p')).filter(el => el.innerText && el.innerText.includes('SOUTH BAY'));
  const links = Array.from(document.querySelectorAll('a')).map(a => ({
    text: a.innerText?.trim(),
    href: a.href,
    parent: a.parentElement?.innerText?.replace(/\n+/g, ' ')
  })).filter(x => x.parent && x.parent.includes('SOUTH BAY'));
  return links;
});
console.log("South Bay links:", southBayLinks);

