async function checkReviews(query) {
  await tool.navigate({ tabId, url: `https://duckduckgo.com/?q=${encodeURIComponent(query)}` });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 15000 });
  return await browserjs(tabId, () => {
    return Array.from(document.querySelectorAll('a[href]'))
      .map(a => ({ text: a.textContent?.trim(), href: a.href }))
      .filter(x => x.text && (x.href.includes('yelp.com') || x.href.includes('facebook.com') || x.href.includes('google.com') || x.href.includes('trustpilot.com')));
  });
}

const legarza = await checkReviews("Legarza Sports reviews Yelp");
